// ------------------------------------------------------------------ Nutzer-Nachricht

function block(tag, inhalt) {
  return `<${tag}>\n${typeof inhalt === "string" ? inhalt : JSON.stringify(inhalt, null, 2)}\n</${tag}>`;
}

export function nachrichtExpose(daten) {
  return `${block("daten", daten)}\n\nErstellen Sie den Exposé-Entwurf nach den Vorgaben.`;
}

export function nachrichtTriage(daten) {
  return `${block("daten", daten)}\n\nBereiten Sie diesen Vorgang nach den Vorgaben auf.`;
}

export function nachrichtFrage({ projekttitel, quellen, frage }) {
  const q = quellen.map((x) => `[${x.id}] ${x.titel}\n${x.text}`).join("\n\n");
  return `${block("quellen", `Projekt: ${projekttitel || "–"}\n\n${q}`)}\n\n${block("frage", frage)}\n\nBeantworten Sie die Frage mit Quellenkennungen.`;
}

export function nachrichtFlaeche(daten, frage) {
  return `${block("daten", daten)}\n\n${frage ? block("frage", frage) : "Keine konkrete Frage: Erklären Sie Status und nächste Schritte."}`;
}

export function nachrichtEntwurf(daten, stichpunkte) {
  return `${block("daten", daten)}${stichpunkte ? `\n\n${block("stichpunkte", stichpunkte)}` : ""}\n\nSchreiben Sie den Nachrichtenentwurf.`;
}
// src/lib/plattform/ki/wissen.js
//
// Wissensbasis des Flächen-Assistenten: ausschließlich Inhalte der eigenen Website
// (Ratgeber unter src/content/ratgeber, Fachlexikon src/data/lexikon.js).
//  - wissensBlock(): stabiler Textblock für den System-Prompt (wird per Prompt-Caching wiederverwendet)
//  - suchen(frage): einfache Stichwortsuche – Quellenliste im KI-Modus und Antwort im Regelmodus
// Nur öffentliche Inhalte, keine Nutzerdaten.

import { INHALTE } from "@/content/ratgeber";
import { BEGRIFFE } from "@/data/lexikon";

const RATGEBER_KATEGORIEN = ["Fläche & Pacht", "Agri-PV & Landwirtschaft", "Recht & Genehmigung"];
const LEXIKON_KATEGORIEN = ["flaeche", "planung"];

const STOPP = new Set(
  "der die das den dem des ein eine einer eines einem einen und oder aber auch als am an auf aus bei bin bis da dann darf dass du er es für gibt hat habe haben hier ich ihr im in ist ja kann können mein meine meiner mit muss nach nicht noch nur ob sich sie sind so über um und von vor was wann warum wer wie wird wo zu zum zur sehr mehr welche welcher welches wieviel viel viele ab bekomme bekommt meiner unsere unser unserer einen eigentlich bitte gilt gelten".split(" ")
);

// Fettdruck entfernen, Markdown-Links behalten (die Oberfläche rendert nur interne Links)
const ohneMarkdown = (s) => String(s || "").replace(/\*\*/g, "");

function woerter(text) {
  return String(text || "")
    .toLowerCase()
    .replace(/[^a-z0-9äöüß§\s-]/g, " ")
    .split(/[\s-]+/)
    .filter((w) => w.length > 2 && !STOPP.has(w));
}

let cache = null;

function eintraege() {
  if (cache) return cache;
  const ratgeber = INHALTE.filter((a) => RATGEBER_KATEGORIEN.includes(a.kategorie)).map((a) => ({
    art: "ratgeber",
    id: a.slug,
    titel: a.kurzTitel || a.title,
    href: `/ratgeber/${a.slug}`,
    kurz: ohneMarkdown(a.excerpt || a.description),
    fazit: (a.kurzFazit || []).map(ohneMarkdown),
    faq: (a.faq || []).map((f) => ({ q: ohneMarkdown(f.q), a: ohneMarkdown(f.a) })),
    stichworte: [a.hauptKeyword, ...(a.keywords || [])].filter(Boolean).join(" "),
  }));
  const lexikon = BEGRIFFE.filter((b) => LEXIKON_KATEGORIEN.includes(b.kategorie)).map((b) => ({
    art: "lexikon",
    id: b.id,
    titel: b.begriff,
    href: `/wissen/lexikon#${b.id}`,
    kurz: ohneMarkdown(b.kurz),
    text: ohneMarkdown(b.text),
    stichworte: (b.synonyme || []).join(" "),
  }));
  const alle = [...ratgeber, ...lexikon].map((e) => ({
    ...e,
    index: {
      titel: new Set(woerter(`${e.titel} ${e.stichworte}`)),
      text: woerter(`${e.kurz} ${(e.fazit || []).join(" ")} ${(e.faq || []).map((f) => `${f.q} ${f.a}`).join(" ")} ${e.text || ""}`),
    },
  }));
  cache = { ratgeber, lexikon, alle };
  return cache;
}

/** Stabiler Wissensblock (Reihenfolge fest → Cache-Präfix bleibt gleich) */
export function wissensBlock() {
  const { ratgeber, lexikon } = eintraege();
  const r = ratgeber
    .map((a) => {
      const teile = [`### ${a.titel} — ${a.href}`, a.kurz];
      if (a.fazit.length) teile.push(`Kernaussagen:\n${a.fazit.map((x) => `- ${x}`).join("\n")}`);
      if (a.faq.length) teile.push(`Häufige Fragen:\n${a.faq.map((f) => `F: ${f.q}\nA: ${f.a}`).join("\n")}`);
      return teile.join("\n");
    })
    .join("\n\n");
  const l = lexikon.map((b) => `- ${b.titel} (${b.href}): ${b.kurz} ${b.text}`).join("\n");
  return `<wissen quelle="Website ÖkoInvest (Ratgeber und Fachlexikon)">\n## Ratgeber\n\n${r}\n\n## Fachlexikon\n\n${l}\n</wissen>`;
}

/** Stichwortsuche: beste Treffer mit Titel, Link, Kurztext und – falls passend – FAQ-Antwort */
export function suchen(frage, { anzahl = 3 } = {}) {
  const w = [...new Set(woerter(frage))];
  if (!w.length) return [];
  const { alle } = eintraege();
  const bewertet = alle
    .map((e) => {
      let punkte = 0;
      for (const x of w) {
        if (e.index.titel.has(x)) punkte += 4;
        else if ([...e.index.titel].some((t) => t.startsWith(x) || x.startsWith(t))) punkte += 2;
        punkte += Math.min(3, e.index.text.filter((t) => t === x || (x.length > 4 && t.startsWith(x))).length);
      }
      if (e.art === "ratgeber") punkte *= 1.15;
      let faq = null;
      if (e.faq?.length) {
        let best = 0;
        for (const f of e.faq) {
          const fw = new Set(woerter(f.q));
          const s = w.filter((x) => fw.has(x)).length;
          if (s > best) {
            best = s;
            faq = f;
          }
        }
        if (best < 2) faq = null;
      }
      return { e, punkte, faq };
    })
    .filter((x) => x.punkte >= 3)
    .sort((a, b) => b.punkte - a.punkte)
    .slice(0, anzahl);
  return bewertet.map(({ e, faq }) => ({ art: e.art, titel: e.titel, href: e.href, text: e.kurz, faq }));
}

// src/lib/plattform/ki/kontext.js
//
// Kontext-Bauer je Anwendungsfall. Grundregel: ERST Rechte prüfen, DANN Kontext zusammenstellen.
// Alle Daten kommen ausschließlich über die Backend-Operationen im Namen des angemeldeten Nutzers
// (b.projekt, b.vorgang, b.flaeche, b.boerseDetail, b.nachrichten …) – diese prüfen Rolle UND
// Eigentum selbst (Demo und Frappe). Was der Nutzer dort nicht sehen darf, kann nie in einen Prompt
// gelangen. Zusätzlich gilt je Fall eine Positivliste der Felder (Datensparsamkeit: z. B. keine
// E-Mail, Telefonnummer oder IP-Adresse im Prompt).
//
// Rückgabe: { objektArt, objektId, daten: {…}, quellen: [{ id, titel, text }], meta: {…} }

import { PlattformFehler } from "../fehler";
import { FLAECHE_NUTZUNG, LAENDER, NETZANSCHLUSS, PROJEKT_TYPEN, VORGANG_TYPEN, BEZUG_ARTEN, BEZUG_LABEL } from "../konstanten";
import { PROZESSE, statusInfo } from "../prozesse";
import { VERTRAULICH_FELDER } from "../oeffentlich";
import { checklisteFlaeche } from "../checkliste";
import { datum, feldLabel, preisText, wertText } from "../format";
import { phaseById } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";

const KENNUNG = /^[A-Za-z0-9][A-Za-z0-9_-]{2,60}$/;

export function kennungPruefen(id, was = "Objekt") {
  const s = String(id || "").trim();
  if (!KENNUNG.test(s)) throw new PlattformFehler(422, `${was} fehlt oder ist ungültig.`);
  return s;
}

const kurzText = (s, max) => {
  const t = String(s ?? "").replace(/\r/g, "").trim();
  return t.length > max ? `${t.slice(0, max)} …` : t;
};

const nichtLeer = (o) => Object.fromEntries(Object.entries(o).filter(([, v]) => v !== undefined && v !== null && v !== "" && !(Array.isArray(v) && !v.length)));

// ------------------------------------------------------------------ Exposé (Anbieter/Admin)

/** Vertrauliche Felder, die als Einordnung dienen dürfen – nie Ortsbezug (Gemeinde, Flurstücke, Netzbetreiber, Einspeisepunkt) */
const EXPOSE_VERTRAULICH_EINORDNUNG = ["sicherung", "planungsrecht", "ertragKwhKwp", "entfernungNetzKm", "verguetung"];

export async function kontextExpose(b, n, { projektId }) {
  const id = kennungPruefen(projektId, "Projekt");
  const p = await b.projekt(n, id); // 404/403 bei fremdem Projekt (Backend prüft Eigentum)
  const phase = p.phase ? phaseById(p.phase) : null;
  const vt = p.vertraulich || {};
  const erfuellt = (p.checkliste?.punkte || []).filter((x) => x.erwartet && x.vorhanden).map((x) => x.label);
  const offen = (p.checkliste?.punkte || []).filter((x) => x.erwartet && x.pflicht && !x.vorhanden).map((x) => x.label);
  return {
    objektArt: "projekt",
    objektId: p.id,
    daten: nichtLeer({
      projekttyp: PROJEKT_TYPEN[p.typ],
      land: LAENDER[p.land],
      bundeslandOderKanton: p.bundesland,
      regionGrob: p.region,
      leistungMwp: p.mwp,
      speicherMwh: p.mwhSpeicher,
      flaecheHa: p.flaecheHa,
      phase: phase?.label,
      typischesRisikoDerPhase: phase?.risiko,
      netzanschluss: NETZANSCHLUSS[p.netzanschluss],
      inbetriebnahmeGeplant: p.codGeplant,
      preisindikation: preisText(p),
      bisherigeBeschreibung: kurzText(p.beschreibung, 4000),
      bisherigeHighlights: p.highlights,
      einordnungIntern: nichtLeer(Object.fromEntries(EXPOSE_VERTRAULICH_EINORDNUNG.map((k) => [VERTRAULICH_FELDER[k], vt[k]]))),
      unterlagenVorhanden: erfuellt,
      unterlagenFehlend: offen,
      datenraumQualitaetProzent: p.checkliste?.quote,
    }),
    quellen: [],
    meta: { projekt: p },
  };
}

// ------------------------------------------------------------------ Triage (Backoffice)

export async function kontextTriage(b, n, { vorgangId }) {
  const id = kennungPruefen(vorgangId, "Vorgang");
  const v = await b.vorgang(n, id);
  const thread = await b.nachrichten(n, "vorgang", id, { markieren: false });
  const k = v.kontakt || {};
  const zusatz = Object.entries(v.daten || {})
    .filter(([, x]) => x !== "" && x !== null && x !== undefined)
    .map(([key, x]) => [feldLabel(key), kurzText(wertText(x), 1500)]);
  const nachrichten = (thread?.nachrichten || [])
    .filter((m) => !m.system)
    .slice(-10)
    .map((m) => ({ von: m.vonAdmin ? "Backoffice" : "Anfragende Person", am: datum(m.am), text: kurzText(m.text, 1500) }));
  return {
    objektArt: "vorgang",
    objektId: v.id,
    daten: nichtLeer({
      vorgangsnummer: v.id,
      typ: VORGANG_TYPEN[v.typ] || v.typ,
      typSchluessel: v.typ,
      status: statusInfo("vorgang", v.status).label,
      eingegangenAm: datum(v.erstelltAm),
      kontakt: nichtLeer({
        anrede: k.anrede,
        vorname: k.vorname,
        nachname: k.nachname,
        unternehmen: k.firma,
        ort: [k.plz, k.ort].filter(Boolean).join(" "),
        land: LAENDER[k.land],
        telefonAngegeben: k.telefon ? "ja" : "nein",
        kontoVorhanden: v.nutzer ? "ja" : "nein",
      }),
      angaben: Object.fromEntries(zusatz),
      nachrichten,
    }),
    quellen: [],
    meta: { vorgang: v, nachrichten: thread?.nachrichten || [] },
  };
}

// ------------------------------------------------------------------ Frag das Projekt (Investor mit Datenraum)

export async function kontextFrage(b, n, { projektId }) {
  const id = kennungPruefen(projektId, "Projekt");
  const d = await b.boerseDetail(n, id, { zaehlen: false });
  // Rechteprüfung VOR dem Zusammenstellen: nur mit freigegebenem Datenraum (NDA), als Anbieter oder Backoffice
  if (!d || !["nda", "eigentuemer", "admin"].includes(d.zugriff)) {
    throw new PlattformFehler(403, "„Frag das Projekt“ steht nach Freigabe Ihres Datenraums (NDA) zur Verfügung.", "verboten");
  }
  const p = d.projekt || {};
  const phase = p.phase ? phaseById(p.phase) : null;
  const quellen = [];
  const q = (titel, text) => {
    const t = String(text ?? "").trim();
    if (!t) return;
    quellen.push({ id: `Q${quellen.length + 1}`, titel, text: kurzText(t, 3000) });
  };
  q(
    "Projektsteckbrief",
    [
      ["Projekttyp", PROJEKT_TYPEN[p.typ]],
      ["Land", LAENDER[p.land]],
      ["Bundesland/Kanton", p.bundesland],
      ["Region", p.region],
      ["Leistung", p.mwp ? `${fmt(p.mwp, 1)} MWp` : ""],
      ["Speicher", p.mwhSpeicher ? `${fmt(p.mwhSpeicher)} MWh` : ""],
      ["Fläche", p.flaecheHa ? `${fmt(p.flaecheHa, 1)} ha` : ""],
      ["Phase", phase?.label],
      ["Netzanschluss", NETZANSCHLUSS[p.netzanschluss]],
      ["Geplante Inbetriebnahme", p.codGeplant],
      ["Preisindikation", preisText(p)],
      ["Datenraum-Qualität", typeof p.datenraumQualitaet === "number" ? `${p.datenraumQualitaet} %` : ""],
    ]
      .filter(([, w]) => w)
      .map(([l, w]) => `${l}: ${w}`)
      .join("\n")
  );
  q("Exposé – Beschreibung", p.beschreibung);
  if (p.highlights?.length) q("Exposé – Highlights", p.highlights.map((h) => `- ${h}`).join("\n"));
  for (const [k, label] of Object.entries(VERTRAULICH_FELDER)) {
    const w = d.vertraulich?.[k];
    if (w !== undefined && w !== null && w !== "") q(`Vertrauliche Angabe – ${label}`, String(w));
  }
  const doks = (d.dokumente || []).slice(0, 60);
  if (doks.length) {
    q(
      "Datenraum – Dokumentenliste (nur Metadaten, Inhalte liegen nicht vor)",
      doks.map((x) => `- ${x.name} · Kategorie ${x.kategorie}${x.checkliste ? ` · Checklistenpunkt ${x.checkliste}` : ""} · hochgeladen ${datum(x.am)}`).join("\n")
    );
  }
  if (phase) q("ÖkoInvest-Marktdaten zur Phase (allgemein, nicht projektspezifisch)", `Übliche Preisspanne „${phase.label}“: ${fmt(phase.preisProKwp.min)}–${fmt(phase.preisProKwp.max)} €/kWp · typisches Risiko: ${phase.risiko}`);
  return { objektArt: "projekt", objektId: p.id, daten: { projekttitel: p.titel }, quellen, meta: { zugriff: d.zugriff, projekt: p, interesseId: d.interesse?.id || null } };
}

